subscribe.Click += (_, _) =>
{
    var address = (email.Value ?? string.Empty).Trim();
    if (!address.Contains('@'))
    {
        email.Error = "Enter a valid email address.";
        return;
    }

    email.Error = null;
    form.IsVisible = false;
    confirmedAddress.Text = address;
    confirmedHost.IsVisible = true;
};
